using System.Text;
using DropFlow.TestSupport;
using static DropFlow.Engines.Media.Tests.Integration.FfmpegSamples;

namespace DropFlow.Engines.Media.Tests.Integration;

/// <summary>
/// The new audio/video sources and outputs with the real FFmpeg (skipped, visibly, when it is missing or lacks an encoder the sample
/// needs). Every source is generated by FFmpeg in the test; results are read back with ffprobe, or with a byte-level check of the
/// container for the animations (an independent reader, not the code that wrote them).
/// </summary>
public class NewFormatsIntegrationTests
{
    private static string Inv(double v) => v.ToString(System.Globalization.CultureInfo.InvariantCulture);

    private static async Task<string> Tone(string path, double seconds, params string[] encode)
    {
        await RunFfmpeg(["-f", "lavfi", "-i", $"sine=frequency=440:duration={Inv(seconds)}:sample_rate=48000", "-ac", "2", .. encode, path]);
        return path;
    }

    [EngineFact(EngineId.Ffmpeg)]
    public async Task A_song_longer_than_40_seconds_becomes_a_40_second_aac_ringtone()
    {
        using var dir = new TempDir();
        var input = await Tone(Path.Combine(dir.Path, "نغمة طويلة.wav"), 55);

        var result = await Run("convert:m4r", input);

        Assert.True(result.Success, result.Error);
        var output = result.Outputs.Single();
        Assert.EndsWith(".m4r", output);
        var info = await Probe(output);
        Assert.Equal("aac", info.Audio!.CodecName);
        Assert.False(info.HasVideo);
        Assert.InRange(info.DurationSeconds!.Value, 39.5, 40.1);
        Assert.Contains("mp4", info.FormatName);           // an MP4-family file under the ringtone's name
        Assert.Equal("note.aud.ringtoneCut|40", result.Note);
    }

    [EngineFact(EngineId.Ffmpeg)]
    public async Task Ac3_and_alac_outputs()
    {
        using var dir = new TempDir();
        var input = await Tone(Path.Combine(dir.Path, "tone.wav"), 3);

        var ac3 = await Run("convert:ac3", input);
        Assert.True(ac3.Success, ac3.Error);
        Assert.Equal("ac3", (await Probe(ac3.Outputs.Single())).Audio!.CodecName);

        var alac = await Run("convert:m4a", input, Opts(("codec", "alac")));
        Assert.True(alac.Success, alac.Error);
        var info = await Probe(alac.Outputs.Single());
        Assert.Equal("alac", info.Audio!.CodecName);
        Assert.InRange(info.DurationSeconds!.Value, 2.9, 3.1);
    }

    [EngineTheory(EngineId.Ffmpeg)]
    [InlineData("tone.wv", new[] { "-c:a", "wavpack" })]
    [InlineData("tone.tta", new[] { "-c:a", "tta" })]
    [InlineData("tone.ac3", new[] { "-c:a", "ac3" })]
    [InlineData("tone.dts", new[] { "-c:a", "dca", "-strict", "-2" })]
    [InlineData("tone.mka", new[] { "-c:a", "flac" })]
    [InlineData("tone.caf", new[] { "-c:a", "pcm_s16be" })]
    public async Task Read_only_audio_sources_convert_to_flac_and_mp3(string name, string[] encode)
    {
        using var dir = new TempDir();
        var input = await Tone(Path.Combine(dir.Path, name), 2, encode);

        foreach (var (target, codec) in new[] { ("flac", "flac"), ("mp3", "mp3") })
        {
            var result = await Run("convert:" + target, input);
            Assert.True(result.Success, $"{name} -> {target}: {result.Error}");
            var info = await Probe(result.Outputs.Single());
            Assert.Equal(codec, info.Audio!.CodecName);
            Assert.InRange(info.DurationSeconds!.Value, 1.8, 2.3);
        }
    }

    [FfmpegFact(FfmpegFeature.Encoder, "libopencore_amrnb")]
    public async Task A_phone_amr_recording_converts_to_mp3()
    {
        using var dir = new TempDir();
        var input = Path.Combine(dir.Path, "call.amr");
        await RunFfmpeg("-f", "lavfi", "-i", "sine=frequency=440:duration=2:sample_rate=8000", "-ac", "1", "-c:a", "libopencore_amrnb", "-b:a", "12.2k", input);

        var result = await Run("convert:mp3", input);
        Assert.True(result.Success, result.Error);
        Assert.Equal("mp3", (await Probe(result.Outputs.Single())).Audio!.CodecName);
    }

    [EngineTheory(EngineId.Ffmpeg)]
    [InlineData("clip.ts", new[] { "-c:v", "mpeg2video", "-c:a", "mp2", "-f", "mpegts" })]
    [InlineData("clip.m2ts", new[] { "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "ac3", "-f", "mpegts", "-mpegts_m2ts_mode", "1" })]
    [InlineData("clip.mts", new[] { "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "ac3", "-f", "mpegts", "-mpegts_m2ts_mode", "1" })]
    [InlineData("clip.3gp", new[] { "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-f", "3gp" })]
    [InlineData("clip.vob", new[] { "-c:v", "mpeg2video", "-c:a", "ac3", "-f", "vob" })]
    [InlineData("clip.mpg", new[] { "-c:v", "mpeg1video", "-c:a", "mp2", "-f", "mpeg" })]
    [InlineData("clip.mpeg", new[] { "-c:v", "mpeg2video", "-c:a", "mp2", "-f", "mpeg" })]
    [InlineData("vcd.dat", new[] { "-c:v", "mpeg1video", "-c:a", "mp2", "-f", "mpeg" })]
    public async Task New_video_sources_convert_to_mp4_and_mp3(string name, string[] encode)
    {
        using var dir = new TempDir();
        var input = Path.Combine(dir.Path, name);
        await RunFfmpeg(["-f", "lavfi", "-i", "testsrc=duration=3:size=320x240:rate=25", "-f", "lavfi", "-i", "sine=frequency=440:duration=3:sample_rate=48000",
            "-shortest", .. encode, input]);

        var mp4 = await Run("convert:mp4", input);
        Assert.True(mp4.Success, $"{name} -> mp4: {mp4.Error}");
        var info = await Probe(mp4.Outputs.Single());
        Assert.Equal("h264", info.Video!.CodecName);
        Assert.Equal("aac", info.Audio!.CodecName);
        Assert.InRange(info.DurationSeconds!.Value, 2.5, 3.6);

        var mp3 = await Run("convert:mp3", input);
        Assert.True(mp3.Success, $"{name} -> mp3: {mp3.Error}");
        Assert.Equal("mp3", (await Probe(mp3.Outputs.Single())).Audio!.CodecName);
    }

    [FfmpegFact(FfmpegFeature.Encoder, "libtheora")]
    public async Task An_ogv_theora_video_converts_to_mp4()
    {
        using var dir = new TempDir();
        var input = Path.Combine(dir.Path, "clip.ogv");
        await RunFfmpeg("-f", "lavfi", "-i", "testsrc=duration=2:size=320x240:rate=25", "-c:v", "libtheora", "-q:v", "5", input);
        var result = await Run("convert:mp4", input);
        Assert.True(result.Success, result.Error);
        Assert.Equal("h264", (await Probe(result.Outputs.Single())).Video!.CodecName);
    }

    [FfmpegFact(FfmpegFeature.Encoder, "libwebp_anim", "libwebp")]
    public async Task Video_becomes_a_looping_animated_webp()
    {
        using var dir = new TempDir();
        var input = await Video(Path.Combine(dir.Path, "مقطع.mp4"), seconds: 2, width: 640, height: 360);

        var result = await Run("convert:webp", input);

        Assert.True(result.Success, result.Error);
        var bytes = await File.ReadAllBytesAsync(result.Outputs.Single());
        Assert.Equal("RIFF", System.Text.Encoding.ASCII.GetString(bytes, 0, 4));
        Assert.Equal("WEBP", System.Text.Encoding.ASCII.GetString(bytes, 8, 4));
        var anim = IndexOf(bytes, "ANIM");
        Assert.True(anim > 0, "no ANIM chunk: not an animation");
        Assert.Equal(0, BitConverter.ToUInt16(bytes, anim + 8 + 4));           // loop count 0 = forever
        Assert.True(Count(bytes, "ANMF") > 10, "expected one frame chunk per frame");
        // canvas width (24-bit, minus one) in the VP8X chunk
        var vp8x = IndexOf(bytes, "VP8X");
        Assert.Equal(480, (bytes[vp8x + 12] | bytes[vp8x + 13] << 8 | bytes[vp8x + 14] << 16) + 1);
    }

    [EngineFact(EngineId.Ffmpeg)]
    public async Task Video_becomes_a_looping_apng()
    {
        using var dir = new TempDir();
        var input = await Video(Path.Combine(dir.Path, "clip.mp4"), seconds: 2, width: 320, height: 240);

        var result = await Run("convert:apng", input);

        Assert.True(result.Success, result.Error);
        var bytes = await File.ReadAllBytesAsync(result.Outputs.Single());
        Assert.Equal(new byte[] { 0x89, 0x50, 0x4E, 0x47 }, bytes[..4]);
        var actl = IndexOf(bytes, "acTL");
        Assert.True(actl > 0, "no acTL chunk: not an animated PNG");
        int Be(int at) => bytes[at] << 24 | bytes[at + 1] << 16 | bytes[at + 2] << 8 | bytes[at + 3];
        Assert.InRange(Be(actl + 4), 20, 40);                                    // about 2 s at 15 fps
        Assert.Equal(0, Be(actl + 8));                                           // plays forever
        Assert.Equal((320, 240), PngSize(result.Outputs.Single()));
    }

    private static int IndexOf(byte[] haystack, string ascii)
    {
        var needle = System.Text.Encoding.ASCII.GetBytes(ascii);
        for (var i = 0; i + needle.Length <= haystack.Length; i++)
            if (haystack.AsSpan(i, needle.Length).SequenceEqual(needle)) return i;
        return -1;
    }

    private static int Count(byte[] haystack, string ascii)
    {
        var needle = System.Text.Encoding.ASCII.GetBytes(ascii);
        var n = 0;
        for (var i = 0; i + needle.Length <= haystack.Length; i++)
            if (haystack.AsSpan(i, needle.Length).SequenceEqual(needle)) n++;
        return n;
    }
}
